export class ResearchBrokerProcess {
  private child?: ChildProcess;
  private availabilityState: BrokerProcessAvailability;
  private buffer = "";
  private startupStderr?: Buffer[];
  private startupStderrBytes = 0;
  private readyAvailability?: BrokerWireAvailability;
  private exited = false;
  private admissionReady = false;
  private readonly workHosts = new Map<string, WorkLedger>();
  private readonly pending = new Map<string, Pending>();
  private readonly settlement = new Map<string, { resolve(): void; work: Set<Promise<unknown>>; cleanup(): void }>();

  constructor(private readonly options: ResearchBrokerProcessOptions) {
    this.availabilityState = options.configuration.mode === "offline" ? "offline" : "unavailable";
  }

  availability(): BrokerProcessAvailability {
    return this.availabilityState;
  }

  canAdmitSession(): boolean {
    return this.admissionReady && Boolean(this.child?.stdin?.writable);
  }

  canDispatch(): boolean {
    return Boolean(this.child?.stdin?.writable);
  }

  async start(): Promise<void> {
    if (this.options.configuration.mode === "offline") {
      this.options.logger?.({ level: "info", event: "research.broker_offline" });
      return;
    }
    if (this.options.configuration.mode === "unavailable") {
      this.options.logger?.({
        level: "warn",
        event: "research.broker_configuration_unavailable",
        reason: this.options.configuration.reason.slice(0, 256)
      });
      return;
    }
    const projectRoot = this.options.projectRoot ?? activeCheckoutRoot();
    const runtime = this.options.runtime ?? "compiled";
    if (this.options.cache) await PersistentSearchCache.prepareHostDirectory(this.options.cache.filePath);
    const launch = buildBrokerLaunch(this.options.cache?.filePath, runtime, projectRoot);
    const credential = this.options.configuration.credential;
    let spawned = false;
    let stderrClosed: Promise<void> | undefined;
    this.startupStderr = [];
    this.startupStderrBytes = 0;
    try {
      const runtimeFailure = this.options.spawnProcess ? undefined : brokerRuntimeFailure(projectRoot, runtime);
      if (runtimeFailure) throw runtimeFailure;
      const child = (this.options.spawnProcess ?? spawn)(launch.executable, launch.arguments, {
        env: brokerEnvironment(
          sanitizedBrokerEnvironment(this.options.environment ?? process.env),
          this.options.cache,
          Boolean(this.options.spawnProcess)
        ),
        stdio: ["pipe", "pipe", "pipe", "pipe"]
      });
      this.child = child;
      stderrClosed = streamClosed(child.stderr);
      child.stdout?.setEncoding("utf8");
      child.stdout?.on("data", (chunk: string) => this.accept(chunk));
      child.stderr?.on("data", (chunk: Buffer) => {
        this.retainStartupStderr(chunk);
        this.options.logger?.({ level: "warn", event: "research.broker_diagnostic" });
      });
      child.stdin?.on("error", () => this.failBrokerInput(child));
      child.once("exit", (exitCode, signal) => {
        if (this.child !== child) return;
        this.settleAll();
        this.child = undefined;
        this.exited = true;
        this.availabilityState = "unavailable";
        this.admissionReady = false;
        this.failAll(new Error("research broker exited"));
        this.options.logger?.({
          level: "warn",
          event: "research.broker_exited",
          exitCode,
          signal: signal ?? "none"
        });
      });
      await waitForSpawn(child);
      spawned = true;
      const bootstrap = child.stdio?.[3] as Writable | null;
      if (!bootstrap) throw new ResearchBrokerStartError("bootstrap_channel_missing", "research bootstrap channel was not created");
      bootstrap.on("error", () => undefined);
      bootstrap.end(`${JSON.stringify({
        contractVersion: 1,
        type: "research.bootstrap",
        provider: this.options.configuration.provider,
        credential
      })}\n`);
      const ready = await this.waitForReady();
      this.startupStderr = undefined;
      this.availabilityState = ready === "available" ? "available" : "unavailable";
      // A configured-unverified broker has completed its credential bootstrap
      // and private control handshake. Its first session tool call performs the
      // provider verification that can promote owner-facing availability.
      this.admissionReady = true;
      this.options.logger?.({ level: "info", event: "research.broker_started", availability: this.availabilityState, provider: "brave" });
    } catch (error) {
      await this.close();
      // Startup output can still be in flight when the process exits.
      if (stderrClosed) await Promise.race([stderrClosed, new Promise((resolve) => setTimeout(resolve, 1_000).unref())]);
      this.availabilityState = "unavailable";
      this.admissionReady = false;
      const failure = error instanceof ResearchBrokerStartError
        ? error
        : !spawned
          ? spawnFailure(error)
          : new ResearchBrokerStartError(
            this.exited ? "exited_before_ready" : "control_failed",
            error instanceof Error ? error.message : "research broker failed before readiness"
          );
      const stderr = Buffer.concat(this.startupStderr ?? []).toString("utf8");
      this.startupStderr = undefined;
      this.options.logger?.({ ...startFailureLogEntry(failure), ...startupStderrDiagnostic(stderr, credential) });
      throw failure;
    }
  }

  private retainStartupStderr(chunk: Buffer): void {
    if (!this.startupStderr) return;
    const remaining = STARTUP_STDERR_LIMIT_BYTES - this.startupStderrBytes;
    if (remaining <= 0) return;
    const retained = chunk.subarray(0, remaining);
    this.startupStderr.push(retained);
    this.startupStderrBytes += retained.length;
  }

  async search(
    context: ResearchContext,
    input: { query: string; maxResults?: number; preferredDomains?: readonly string[] },
    signal?: AbortSignal
  ): Promise<ResearchResult<readonly RankedSearchResult[]>> {
    return this.call("research.request", { context, operation: "search", input }, signal) as Promise<ResearchResult<readonly RankedSearchResult[]>>;
  }

  async fetch(context: ResearchContext, input: FetchInput, signal?: AbortSignal): Promise<ResearchResult<FetchResult>> {
    return this.call("research.request", { context, operation: "fetch", input }, signal) as Promise<ResearchResult<FetchResult>>;
  }

  async transcript(context: ResearchContext, input: TranscriptInput, signal?: AbortSignal): Promise<ResearchResult<YoutubeTranscriptResult>> {
