import { resolveSearchCacheConfiguration } from "./config.js";
import { createHash } from "node:crypto";
import { readdirSync, readFileSync } from "node:fs";
import { CORE_RELEASE } from "./core/service.js";
import { WORK_DIMENSIONS } from "./core/work.js";
import { ResearchError } from "./contracts.js";
import { GITHUB_EXCLUDED_SOURCE_POLICY } from "./core/policy.js";

import type { ResearchTrialPolicy } from "./trialTypes.js";
export type { ResearchTrialPolicy } from "./trialTypes.js";

/** Capture this process generation before admitting trial work. */
function fingerprintResearchRuntime() {
  const base = new URL("./", import.meta.url);
  const extension = import.meta.url.endsWith(".ts") ? ".ts" : ".js";
  const files = ["core", "."].flatMap(directory => readdirSync(new URL(`${directory}/`, base))
    .filter(name => name.endsWith(extension) && !name.includes(".test.") && !name.endsWith(".d.ts"))
    .map(name => `${directory}/${name}`)).sort();
  files.push(...["storage/research-trials", "storage/store", "storage/task-onboarding-and-workflow-start", "storage/runtime-recovery",
    "storage/validation-evidence-and-execution", "storage/research-policy-and-evidence", "storage/migrations",
    "commandExecution/dispatcher", "planner/toolDispatcher", "api/application-sessions", "api/application-lifecycle", "api/application-workflow", "owner/main"]
    .map(name => `../${name}${extension}`), "../../package-lock.json");
  const hashes = files.map(name => [name, createHash("sha256").update(readFileSync(new URL(name, base))).digest("hex")]);
  const coreArtifactDigest = createHash("sha256").update(JSON.stringify(hashes.filter(([name]) => name!.startsWith("core/")))).digest("hex");
  const cacheConfiguration = resolveSearchCacheConfiguration(process.env);
  hashes.push(["cacheConfiguration", JSON.stringify(cacheConfiguration)]);
  return { ...CORE_RELEASE, coreArtifactDigest, cacheConfiguration, artifactDigest: createHash("sha256").update(JSON.stringify(hashes)).digest("hex"),
    ranker: "lexical-v2-initial-4", cache: "owner_namespaced", automaticRetries: 0, workContractVersion: 1 } as const;
}

const startupIdentity = Object.freeze(fingerprintResearchRuntime());

/** Never relabel already loaded modules after an on-disk rebuild. Restart is required. */
export function researchRuntimeIdentity() {
  if (!researchRuntimeMatches(startupIdentity.artifactDigest)) {
    throw new ResearchError("invalid_request", "Research runtime artifact drift; restart the owner and broker");
  }
  return structuredClone(startupIdentity);
}

export function researchRuntimeMatches(artifactDigest: string): boolean {
  try {
    return artifactDigest === startupIdentity.artifactDigest &&
      fingerprintResearchRuntime().artifactDigest === startupIdentity.artifactDigest;
  } catch { return false; }
}

export function parseResearchTrialPolicy(value: unknown): ResearchTrialPolicy {
  const p = value as ResearchTrialPolicy;
  const fail = (): never => { throw new ResearchError("invalid_request", "benchmark research policy is invalid"); };
  const keys = ["contractVersion", "trialId", "workflowCommandId", "cohortDigest", "artifactDigest", "policy", "limits", "roleCallLimits", "deadlineAt", "networkedOperation", "cache", "automaticRetries",
    ...(p?.contractVersion === 2 ? ["sourcePolicy"] : [])].sort().join();
  if (!p || typeof p !== "object" || Array.isArray(p) || Object.keys(p).sort().join() !== keys) fail();
  if (p.trialId === "runtime") fail(); // Reserved runtime-identity API route.
  if (![1, 2].includes(p.contractVersion) || p.networkedOperation !== "denied" || p.cache !== "owner_namespaced" || p.automaticRetries !== 0) fail();
  if (p.contractVersion === 2) {
    const source = p.sourcePolicy;
    const expected = GITHUB_EXCLUDED_SOURCE_POLICY;
    if (!source || Object.keys(source).sort().join() !== Object.keys(expected).sort().join() ||
      source.profileId !== expected.profileId || source.version !== expected.version || source.domainSetId !== expected.domainSetId ||
      source.domains.join() !== expected.domains.join() || source.matchingAlgorithm !== expected.matchingAlgorithm ||
      source.searchFiltering !== expected.searchFiltering || source.fetchEnforcement !== expected.fetchEnforcement || source.fallback !== expected.fallback) fail();
  }
  for (const id of [p.trialId, p.workflowCommandId]) if (typeof id !== "string" || !/^[A-Za-z0-9._:-]{1,128}$/u.test(id)) fail();
  for (const hash of [p.cohortDigest, p.artifactDigest, p.policy?.hash]) if (typeof hash !== "string" || !/^[a-f0-9]{64}$/u.test(hash)) fail();
  if (!p.policy || Object.keys(p.policy).sort().join() !== "hash,id,version" || typeof p.policy.id !== "string" ||
    !/^[A-Za-z0-9._:-]{1,128}$/u.test(p.policy.id) || !Number.isSafeInteger(p.policy.version) || p.policy.version < 1) fail();
  if (!p.limits || Object.keys(p.limits).sort().join() !== [...WORK_DIMENSIONS].sort().join()) fail();
  for (const n of Object.values(p.limits)) if (!Number.isSafeInteger(n) || n < 0) fail();
  if (p.limits.calls > 4096 || p.limits.scoringTokens !== 0 || p.limits.scoringWindows !== 0) fail();
  if (!p.roleCallLimits || Object.keys(p.roleCallLimits).sort().join() !== "implementer,planner") fail();
  for (const n of Object.values(p.roleCallLimits)) if (!Number.isSafeInteger(n) || n < 0 || n > p.limits.calls) fail();
  if (typeof p.deadlineAt !== "string" || !Number.isFinite(Date.parse(p.deadlineAt)) || new Date(p.deadlineAt).toISOString() !== p.deadlineAt) fail();
  return structuredClone(p);
}

export function trialResearchGuidance(policy: ResearchTrialPolicy): string {
  return `# Benchmark research assignment\nTrial: ${policy.trialId}; cohort: ${policy.cohortDigest}; artifact: ${policy.artifactDigest}.\n` +
    `All roles share ${policy.limits.calls} research calls. Planner sublimit: ${policy.roleCallLimits.planner}; implementer sublimit: ${policy.roleCallLimits.implementer}. ` +
    `The aggregate and sublimit must both admit a call. Replacing or reopening a session does not replenish either allowance. ` +
    `Research deadline: ${policy.deadlineAt}. No automatic retries; an explicit retry is another call. Search cache entries and simultaneous identical requests are isolated to this trial; cache hits consume calls without a new provider attempt. ` +
    `Reviewer research is denied. Planner evidence reuse remains planner-originated and costs no new call; independent implementer calls remain separately attributed. ` +
    `Only shared lexical search/fetch is admitted. networked_operation and work-tracker network operations are denied, including validation recovery. Use preprovisioned dependencies and restricted commands. ` +
    `${policy.contractVersion === 2 ? "The github-excluded-v1 source policy rejects GitHub-family search results and every direct or redirected fetch before connection. " : "Public sources including upstream solutions are allowed; disclose observed solution exposure without claiming its absence. "}` +
    `Never access hidden tests, gold patches, scores, or other trials.`;
}

